/*
 * Wriggler source artwork.
 *
 * The eight original phase headers were combined into this single file for
 * one obvious asset home instead of eight tiny generated
 * headers in the project root.
 *
 * Pixel encoding in the source data:
 *   0x9 = white/body highlight
 *   0xA = black/detail
 *   0xB = original red/background, treated by the loader as transparent
 *
 * Source byte packing is high-nibble-left / low-nibble-right.  The loader in
 * egg_C9_wriggler.c converts this to the internal 2dfx resource RAM packing.
 */

#define WRIG_SOURCE_WIDTH          64u
#define WRIG_SOURCE_HEIGHT         16u
#define WRIG_SOURCE_BYTES_PER_ROW  32u

/* Compatibility names used by the Wriggler constants. */
